// ListWorkflowTemplates 列出 Nexus Workflow 模板。
func (c *Client) ListWorkflowTemplates(ctx context.Context, status *string, q *string, includeHistory *bool, view *string) (json.RawMessage, error) {
	var response json.RawMessage
	endpointPath := "/v1/workflow-templates"
	queryValues := url.Values{}
	if status != nil {
		queryValues.Set("status", *status)
	}
	if q != nil {
		queryValues.Set("q", *q)
	}
	if includeHistory != nil {
		queryValues.Set("include_history", strconv.FormatBool(*includeHistory))
	}
	if view != nil {
		queryValues.Set("view", *view)
	}
	if encodedQuery := queryValues.Encode(); encodedQuery != "" {
		endpointPath += "?" + encodedQuery
	}
	err := c.doJSON(ctx, http.MethodGet, endpointPath, nil, &response)
	return response, err
}

